INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('WOQ2FPP4', 'معرفی', 'ایران فارما چیست؟', 'نمایشگاه بین‌المللی ایران‌فارما، بزرگ‌ترین رویداد تخصصی و بین‌المللی صنعت داروسازی ایران و یکی از معتبرترین نمایشگاه‌های این حوزه در منطقه خاورمیانه و MENA است. این رویداد با هدف توسعه تعاملات تجاری، معرفی فناوری‌های نوین، ایجاد فرصت‌های سرمایه‌گذاری و تقویت همکاری‌های داخلی و بین‌المللی برگزار می‌شود و میزبان شرکت‌های داروسازی، تولیدکنندگان مواد اولیه، تجهیزات، بسته‌بندی، خدمات فنی و فعالان زنجیره تأمین دارو از کشورهای مختلف جهان است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('FIKR6ABJ', 'معرفی', 'چرا نمایشگاه بین‌المللی ایران فارما اهمیت دارد؟', 'این نمایشگاه مهم‌ترین نقطه اتصال فعالان صنعت داروسازی، شرکت‌های تولیدی، تأمین‌کنندگان، شرکت‌های دانش‌بنیان، سرمایه‌گذاران، دانشگاه‌ها و نهادهای حاکمیتی است و نقش مهمی در توسعه صنعت داروی کشور ایفا می‌کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('64H7W88M', 'معرفی', 'شرکت در نمایشگاه بین‌المللی ایران فارما چه مزایایی دارد؟', 'حضور در این نمایشگاه فرصتی برای توسعه بازار، معرفی محصولات و خدمات، جذب مشتریان جدید، شبکه‌سازی حرفه‌ای، جذب سرمایه و آشنایی با آخرین دستاوردهای صنعت داروسازی است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('JNNF5LQT', 'معرفی', 'هدف از برگزاری ایران فارما چیست؟', 'ایران‌فارما بستری برای معرفی توانمندی‌ها و ظرفیت‌های صنعت داروسازی، توسعه همکاری‌های فناورانه، گسترش تعاملات تجاری و بین‌المللی، ایجاد فرصت‌های سرمایه‌گذاری و تقویت بازارهای صادراتی است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('KKS1D1ZV', 'معرفی', 'نمایشگاه بین‌المللی ایران فارما چه بخش‌هایی دارد و هر بخش چه نقشی ایفا می‌کند؟', 'نمایشگاه بین‌المللی ایران فارما شامل بخش‌های متنوع نمایشگاهی، علمی، تجاری و فناورانه است که هر کدام با هدف پاسخ‌گویی به نیازهای مختلف فعالان صنعت داروسازی طراحی شده‌اند. بخش نمایشگاهی، محل معرفی محصولات، خدمات و توانمندی شرکت‌هاست؛ بخش‌های علمی و محتوایی به انتقال دانش و بررسی چالش‌های صنعت می‌پردازند و بخش‌های تجاری نیز فرصت ایجاد ارتباطات جدید و همکاری‌های اقتصادی را فراهم می‌کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('MHXG69P4', 'معرفی', 'حضور در نمایشگاه بین‌المللی ایران فارما چه فرصتی برای شرکت‌ها ایجاد می‌کند؟', 'حضور در این رویداد فرصتی برای معرفی برند، نمایش توانمندی‌ها، جذب مشتریان جدید، توسعه همکاری‌های تجاری، شناسایی فرصت‌های بازار، مذاکره با شرکای بالقوه و ایجاد ارتباط مستقیم با تصمیم‌گیران اصلی صنعت داروسازی فراهم می‌کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('W4JS6969', 'معرفی', 'نمایشگاه بین‌المللی ایران فارما چگونه به توسعه صنعت داروسازی کمک می‌کند؟', 'این نمایشگاه با ایجاد فضای تعامل میان صنعتگران، متخصصان، دانشگاه‌ها، شرکت‌های فناور و نهادهای مرتبط، زمینه تبادل تجربه، معرفی فناوری‌های جدید، توسعه همکاری‌های علمی و تجاری و حرکت به سمت نوآوری در صنعت داروسازی را فراهم می‌کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('XU6JD4A3', 'معرفی', 'آیا نمایشگاه بین‌المللی ایران فارما برای شرکت‌های خارجی نیز فرصت ایجاد می‌کند؟', 'بله. این نمایشگاه با فراهم کردن بستر ارتباط میان شرکت‌های داخلی و بین‌المللی، فرصت مناسبی برای شناخت بازار ایران، ایجاد همکاری‌های تجاری، انتقال فناوری، توسعه صادرات و ارتباط با تولیدکنندگان و فعالان منطقه‌ای فراهم می‌کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('UZ8QNUDL', 'معرفی', 'آیا بازدید از نمایشگاه بین‌المللی ایران فارما برای دانشجویان ارزش رزومه‌ای دارد؟', 'حضور در یک رویداد تخصصی و بین‌المللی صنعت داروسازی می‌تواند نشان‌دهنده علاقه و پیگیری دانشجو نسبت به حوزه تخصصی خود باشد و در کنار تجربه عملی، به شناخت بهتر فضای حرفه‌ای کمک کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('50LDC9DS', 'معرفی', 'یک دانشجو قبل از بازدید از نمایشگاه بین‌المللی ایران فارما چه کاری باید انجام دهد؟', 'بهتر است قبل از حضور، شرکت‌های حاضر، حوزه‌های مورد علاقه، برنامه‌های علمی و بخش‌های مختلف نمایشگاه را بررسی کند تا بازدید هدفمندتری داشته باشد و بتواند بیشترین استفاده را از فرصت ارتباط با فعالان صنعت ببرد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('MYEPQ5U3', 'معرفی', 'آیا نمایشگاه بین‌المللی ایران فارما فقط یک نمایشگاه تجاری است؟', 'خیر. نمایشگاه بین‌المللی ایران فارما فراتر از یک نمایشگاه تجاری است و به عنوان یک پلتفرم جامع برای توسعه صنعت داروسازی، تبادل دانش، شبکه‌سازی حرفه‌ای و ایجاد همکاری‌های راهبردی شناخته می‌شود.در کنار بخش نمایشگاهی، مجموعه‌ای از رویدادهای علمی، آموزشی، تجاری و فناورانه برگزار می‌شود که فرصت تعامل میان تولیدکنندگان، تأمین‌کنندگان، پژوهشگران، دانشگاهیان، سرمایه‌گذاران، شرکت‌های دانش‌بنیان و مدیران ارشد صنعت را فراهم می‌کند.شرکت‌کنندگان علاوه بر معرفی محصولات و خدمات خود، می‌توانند در نشست‌های تخصصی، پنل‌های علمی، کارگاه‌های آموزشی و جلسات انتقال تجربه حضور یافته و با آخرین روندها، فناوری‌ها و چالش‌های صنعت داروسازی آشنا شوند.همچنین بخش‌هایی مانند استیج ایران فارما، ایران فارما کست، ایران فارما بریج و پردیس ایران فارما بستری برای ارائه نوآوری‌ها، گفتگوهای تخصصی، توسعه همکاری‌های تجاری، جذب سرمایه و ارتباط میان صنعت و اکوسیستم فناوری فراهم می‌کنند.جلسات B2B و ملاقات‌های تجاری هدفمند نیز امکان مذاکره مستقیم میان شرکت‌های داخلی و خارجی را فراهم کرده و فرصت‌های جدیدی برای توسعه بازار، صادرات، انتقال فناوری و مشارکت‌های بین‌المللی ایجاد می‌کنند.به همین دلیل، نمایشگاه بین‌المللی ایران فارما تنها محل نمایش محصولات نیست؛ بلکه رویدادی است که دانش، فناوری، تجارت، سرمایه‌گذاری و شبکه‌سازی را در کنار یکدیگر قرار می‌دهد و به رشد و توسعه صنعت داروسازی کشور کمک می‌کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('0W5IQ75P', 'اطلاعات، خدمات', 'آیا خدمات ترجمه وجود دارد؟', 'خدمات ترجمه در تعدادی از سالن‌ها و برای برنامه‌های بین‌المللی وجود دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('N24H6NP7', 'خدمات', 'نقشه غرفه‌سازی چه زمانی باید تحویل شود؟', 'حداکثر تا ۱ شهریور ۱۴۰۵.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('L0PZ3CQ3', 'معرفی', 'آیا دانشجویان می‌توانند در برنامه‌های علمی نمایشگاه شرکت کنند؟', 'بله. برنامه‌های علمی، نشست‌های تخصصی، ارائه‌ها و بخش‌های محتوایی نمایشگاه می‌تواند فرصتی برای افزایش دانش تخصصی، آشنایی با موضوعات روز صنعت و بهره‌مندی از تجربیات متخصصان باشد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('0BD0PHSU', 'معرفی', 'آیا حضور در نمایشگاه بین‌المللی ایران فارما فرصت شغلی ایجاد می‌کند؟', 'بله. بسیاری از شرکت‌ها در نمایشگاه فرصت مناسبی برای شناسایی نیروهای متخصص، معرفی مسیرهای همکاری و ارتباط با استعدادهای جوان پیدا می‌کنند. دانشجویان، فارغ‌التحصیلان و افراد جویای موقعیت کاری بهتر نیز می‌توانند با شناخت بهتر شرکت‌ها و نیازهای بازار، مسیر شغلی خود را هدفمندتر انتخاب کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('M9N2OQ3Z', 'معرفی', 'دانشجویان در نمایشگاه بین‌المللی ایران فارما چه چیزهایی می‌توانند یاد بگیرند؟', 'دانشجویان می‌توانند با آخرین دستاوردهای صنعت داروسازی، فرآیند تولید دارو، فناوری‌های نوین، تجهیزات و ماشین‌آلات دارویی، حوزه تحقیق و توسعه، فرصت‌های کارآفرینی و مسیرهای ورود به صنعت آشنا شوند. نشست‌های انتقال تجربه و چالش‌ها و مسابقات دانشجویی از بخش‌های مورد استقبال دانشجویان است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('LJ4GK8Z9', 'معرفی', 'چرا یک دانشجو باید نمایشگاه بین‌المللی ایران فارما را تجربه کند؟', 'زیرا این نمایشگاه فرصتی است تا دانشجو از فضای دانشگاهی فاصله بگیرد و با واقعیت‌های صنعت، فرصت‌های آینده، فناوری‌های جدید، مسیرهای شغلی و افرادی که در این حوزه فعالیت می‌کنند از نزدیک آشنا شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ISWZ9O72', 'معرفی', 'آیا نمایشگاه بین‌المللی ایران فارما فقط برای دانشجویان داروسازی است؟', 'خیر. این نمایشگاه برای دانشجویان رشته‌های مختلف مرتبط با صنعت سلامت نیز جذاب است؛ از جمله داروسازی، بیوتکنولوژی، علوم آزمایشگاهی، شیمی، مهندسی شیمی، مهندسی پزشکی، مدیریت کسب‌وکار، فناوری اطلاعات سلامت و سایر حوزه‌های مرتبط.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('VO63W3DY', 'معرفی', 'آیا دانشجویان هم می‌توانند از نمایشگاه بین‌المللی ایران فارما بازدید کنند؟', 'بله. نمایشگاه بین‌المللی ایران فارما فقط برای شرکت‌ها و فعالان تجاری نیست؛ دانشجویان رشته‌های مرتبط با داروسازی، علوم پزشکی، زیست‌فناوری، شیمی، مهندسی، مدیریت و سایر حوزه‌های مرتبط با صنعت سلامت نیز می‌توانند از این رویداد بازدید کنند و با فضای واقعی صنعت آشنا شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('UZ36CZ1U', 'معرفی', 'آیا دانشجویان می‌توانند با شرکت‌های دارویی ارتباط برقرار کنند؟', 'بله. یکی از مهم‌ترین مزایای حضور دانشجویان در نمایشگاه بین‌المللی ایران فارما، امکان گفت‌وگو با مدیران، متخصصان و کارشناسان شرکت‌های دارویی، آشنایی با فعالیت‌های آن‌ها و ایجاد ارتباط برای فرصت‌های کارآموزی، همکاری پژوهشی یا شغلی است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('U4NN5ZKF', 'معرفی', 'حضور در نمایشگاه بین‌المللی ایران فارما چه کمکی به دانشجویان می‌کند؟', 'این نمایشگاه فرصتی برای آشنایی دانشجویان با زنجیره کامل صنعت داروسازی، شرکت‌های فعال، فرصت‌های شغلی، فناوری‌های جدید، مسیرهای تحقیقاتی و نیازهای واقعی بازار فراهم می‌کند و می‌تواند دید بهتری نسبت به آینده حرفه‌ای آن‌ها ایجاد کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('IHDWQI8C', 'معرفی', 'چرا نمایشگاه بین‌المللی ایران فارما را می‌توان یک نقطه اتصال برای صنعت داروسازی دانست؟', 'زیرا در این رویداد تمامی حلقه‌های زنجیره دارو، از تولیدکنندگان و تأمین‌کنندگان تا متخصصان، پژوهشگران، سرمایه‌گذاران و تصمیم‌گیران صنعت در کنار هم قرار می‌گیرند و فرصت ایجاد ارتباط، همکاری و توسعه فراهم می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('7N54E8UN', 'معرفی', 'نمایشگاه بین‌المللی ایران فارما چه نقشی در معرفی نوآوری‌ها دارد؟', 'این نمایشگاه فضایی برای معرفی فناوری‌های جدید، محصولات نوآورانه، دستاوردهای تحقیق و توسعه و توانمندی شرکت‌های دانش‌بنیان فراهم می‌کند تا این نوآوری‌ها به فعالان صنعت، سرمایه‌گذاران و بازار معرفی شوند. بسیاری از رونمایی‌های محصول و معرفی محصولات جدید در این نمایشگاه انجام می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('J1QMDM13', 'معرفی', 'چرا شرکت‌های دارویی باید حضور مستمر در نمایشگاه بین‌المللی ایران فارما داشته باشند؟', 'حضور مستمر باعث افزایش شناخت برند، حفظ ارتباط با فعالان صنعت، آگاهی از تغییرات بازار، مشاهده عملکرد رقبا، شناسایی فرصت‌های جدید و تقویت جایگاه شرکت در زنجیره صنعت داروسازی می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('C86U2SV9', 'معرفی', 'تفاوت حضور در نمایشگاه بین‌المللی ایران فارما با تبلیغات معمولی چیست؟', 'در تبلیغات معمولی، ارتباط با مخاطب معمولاً یک‌طرفه است؛ اما در نمایشگاه بین‌المللی ایران فارما شرکت‌ها می‌توانند به‌صورت مستقیم با مخاطبان تخصصی گفتگو کنند، نیازهای بازار را بشناسند، مذاکرات تجاری انجام دهند و ارتباطات بلندمدت ایجاد کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('GL0GSLPN', 'معرفی', 'برگزارکننده نمایشگاه چه نهادی است؟', 'این رویداد توسط سندیکای صاحبان صنایع داروهای انسانی ایران و دبیرخانه اجرایی نمایشگاه بین‌المللی ایران‌فارما - موسسه رسایش برگزار می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('D7N90WC8', 'معرفی', 'نمایشگاه بین‌المللی ایران فارما چه نقشی در توسعه صادرات دارد؟', 'این نمایشگاه با حضور هیئت‌های تجاری و شرکت‌های خارجی، بستری مناسب برای معرفی توانمندی‌های صنعت داروسازی ایران و ایجاد همکاری‌های صادراتی و بین‌المللی فراهم می‌کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('WJNCUXQ9', 'معرفی', 'چه فرصت‌هایی برای شرکت‌های دانش‌بنیان در نمایشگاه بین‌المللی ایران فارما وجود دارد؟', 'شرکت‌های دانش‌بنیان می‌توانند فناوری‌ها و محصولات نوآورانه خود را معرفی کرده، با سرمایه‌گذاران و شرکت‌های صنعتی ارتباط برقرار کنند و فرصت‌های همکاری و تجاری‌سازی فناوری را توسعه دهند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('YDMZKSRG', 'معرفی', 'نمایشگاه بین‌المللی ایران فارما چه تأثیری بر برند شرکت‌ها دارد؟', 'حضور در این رویداد موجب افزایش اعتبار برند، ارتقای جایگاه حرفه‌ای شرکت‌ها و معرفی توانمندی‌های آن‌ها به طیف گسترده‌ای از فعالان صنعت داروسازی می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('EFCQMAEZ', 'معرفی', 'چرا باید نمایشگاه بین‌المللی ایران فارما را از نزدیک تجربه کرد؟', 'زیرا در مدت چند روز می‌توان با مهم‌ترین شرکت‌ها، مدیران، متخصصان و تصمیم‌گیران صنعت داروسازی دیدار کرد، از آخرین تحولات بازار مطلع شد و فرصت‌های جدید همکاری و توسعه کسب‌وکار را شناسایی کرد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('GIFOLA51', 'اطلاعات', 'نمایشگاه در چه تاریخی برگزار می‌شود؟', 'یازدهمین نمایشگاه بین‌المللی ایران‌فارما از 1 تا 3 مهر 1405 برگزار می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('P5E0LRSQ', 'اطلاعات', 'ساعت بازدید چیست؟', 'ساعات بازدید نمایشگاه از ۱ تا ۳ مهرماه از ساعت ۹:۰۰ صبح تا ۵:۳۰ بعدازظهر خواهد بود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('I49GC7HV', 'اطلاعات', 'محل برگزاری کجاست؟', 'این نمایشگاه در مصلای بزرگ تهران برگزار می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('LK4KBZRS', 'اطلاعات، خدمات', 'چگونه به محل نمایشگاه دسترسی پیدا کنم؟', 'محل برگزاری (مصلای بزرگ تهران)، از طریق خودروی شخصی (ورودی های بزرگراه رسالت، خیابان شهید قنبرزاده، و خیابان شهید بهشتی)، از طریق مترو (ایستگاه های شهید بهشتی و مصلا) و اتوبوس (ایستگاه مصلا) قابل دسترسی است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('1H1BQAIG', 'اطلاعات، خدمات', 'آیا پارکینگ وجود دارد؟', 'بله، پارکینگ‌هایی با ورودی‌های مجزا برای غرفه‌داران و بازدیدکنندگان وجود دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('B8D2V6OG', 'اطلاعات، خدمات', 'هزینه بازدید چقدر است؟', 'بازدید از تمام فضاهای نمایشگاهی رایگان است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('6WJRLGYJ', 'اطلاعات، ثبت‌نام', 'آیا ثبت‌نام قبلی لازم است؟', 'بله، برای بازدید از نمایشگاه باید ثبت‌نام کرده باشید که از طریق سایت و پلتفرم این رویداد به نشانی IPHEXPO.COM انجام آن امکان‌پذیر است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('P4MYPEP6', 'اطلاعات', 'آیا بازدید برای عموم آزاد است؟', 'نمایشگاه بین‌المللی ایران‌فارما یک رویداد تخصصی است و مشابه هر رویداد تخصصی بین‌المللی دیگر برای عموم مخاطبان و علاقه‌مندان آزاد و بازدید از آن رایگان است', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('3MWAVH5Q', 'اطلاعات، ثبت‌نام', 'آیا بازدیدکنندگان خارجی می‌توانند شرکت کنند؟', 'بازدیدکنندگان خارجی نیز می‌توانند پس از ثبت‌نام از نمایشگاه بازدید نمایند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('YFFAEEAZ', 'اطلاعات', 'چه تعداد شرکت در نمایشگاه حضور دارند؟', 'تعداد شرکت‌های حاضر در یازدهمین دوره نمایشگاه ایران‌فارما هنوز نهایی نشده است، اما طی سال‌های گذشته، هر سال بیش از 700 شرکت در نمایشگاه حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('BJJBW8U8', 'اطلاعات', 'چند کشور در نمایشگاه شرکت می‌کنند؟', 'تعداد کشور‌های حاضر در یازدهمین دوره نمایشگاه ایران‌فارما هنوز نهایی نشده است، اما طی سال‌های گذشته، هر سال بیش از 30 کشور در نمایشگاه حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('2ODQH1WN', 'اطلاعات', 'آیا اپلیکیشن نمایشگاه وجود دارد؟', 'نمایشگاه اپلیکیشن رسمی ندارد اما پلتفرم رسمی این رویداد به نشانی IPHEXPO.COM قابل استفاده و ارائه خدمت به عموم علاقه‌مندان و مخاطبان این رویداد است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('AAL3GR0H', 'اطلاعات', 'آیا نقشه سالن‌ها موجود است؟', 'نقشه نمایشگاه و سالن‌ها از طریق  پلتفرم رسمی این رویداد به نشانی IPHEXPO.COM قابل رویت است و با کلیک روی هر نقطه میتوانید نام آن فضا یا غرفه را دریافت کنید', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ACDCQJOQ', 'اطلاعات، ثبت‌نام', 'آیا امکان بازدید گروهی وجود دارد؟', 'امکان بازدید گروهی پس از ثبت‌نام و هماهنگی با دبیرخانه وجود دارد. تورهای صنعتی و دانشجویی در سه روز برگزاری این نمایشگاه برگزار می‌شود و علاقه‌مندان در این سه روز  فرصت بازدید تخصصی از غرفه‌ها را نیز خواهند داشت.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('QLD44H8A', 'اطلاعات', 'آیا خدمات راهنما ارائه می‌شود؟', 'دفترچه راهنما در پلتفرم رسمی این رویداد به نشانی IPHEXPO.COM قابل بهره‌برداری است و همچنین علاقه‌مندان در در محل نمایشگاه نیز می‌توانند از دفترچه‌ها و خدمات راهنما استفاده نمایند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('Q2YT4XLK', 'اطلاعات، خدمات', 'آیا اینترنت در نمایشگاه موجود است؟', 'اینترنت به صورت اختصاصی برای نمایشگاه وجود ندارد. مشارکت‌کنندگان می‌توانند از تجهیزات شخصی خود برای دسترسی به اینترنت استفاده کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('WR39BCV9', 'معرفی', 'کدام صنایع در نمایشگاه حضور دارند؟', 'محصولات نهایی (Finished Products)، مواد اولیه دارویی (API)، محصولات بیوتکنولوژی، فناوری‌های آزمایشگاهی، خدمات چاپ و بسته‌بندی، تجهیزات پزشکی، محصولات سلامت‌محور، آرایشی و بهداشتی و صنایع وابسته، مکمل‌های رژیمی و غذایی، داروهای گیاهی، ماشین‌آلات و تاسیسات حمایتی، شرکت‌های ارائه دهنده خدمات سلامت دیجیتال و ... در نمایشگاه حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('AZQ3O893', 'معرفی', 'چه افرادی از نمایشگاه بازدید می‌کنند؟', 'تولیدکنندگان دارو، تأمین‌کنندگان مواد اولیه دارویی، متخصصان سلامت، توزیع‌کنندگان، واردکنندگان، صادرکنندگان، پژوهشگران، سرمایه‌گذاران و مدیران صنعت داروسازی، دانشجویان، اساتید دانشگاهی و ... می‌توانند از حضور در این نمایشگاه بهره‌مند شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('UT301FSD', 'معرفی', 'چه چیزی نمایشگاه ایران‌فارما را متمایز می‌کند؟', 'این رویداد یکی از مهم‌ترین پلتفرم‌های تخصصی صنعت داروسازی در منطقه است که تولیدکنندگان، تأمین‌کنندگان، نهادهای نظارتی و متخصصان سلامت را گرد هم می‌آورد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('X2ITDMQV', 'معرفی', 'چرا باید در نمایشگاه ایران‌فارما شرکت کنم؟', '1. دسترسی مستقیم به تصمیم‌گیران صنعت دارودر IRANPHARMA مدیران عامل، مدیران فنی، مدیران خرید، مسئولان تأمین، سرمایه‌گذاران، نهادهای حاکمیتی و فعالان زنجیره تأمین دارو حضور دارند. این فرصت امکان مذاکرات مستقیم و ایجاد همکاری‌های جدید را فراهم می‌کند.2. توسعه بازار و جذب مشتریان جدیدنمایشگاه بستری ایده‌آل برای معرفی محصولات، خدمات و توانمندی‌های شرکت‌ها به مخاطبان تخصصی است. بسیاری از مذاکرات تجاری و قراردادهای همکاری از همین ارتباطات اولیه شکل می‌گیرند.3. فرصت‌های صادراتی و همکاری‌های بین‌المللیحضور شرکت‌ها، هیئت‌های تجاری و بازدیدکنندگان خارجی، فرصت مناسبی برای شناسایی بازارهای جدید، توسعه صادرات و ایجاد همکاری‌های بین‌المللی فراهم می‌کند.4. معرفی نوآوری‌ها و فناوری‌های روزIRANPHARMA ویترینی از آخرین دستاوردهای صنعت داروسازی، بیوتکنولوژی، تجهیزات، مواد اولیه، بسته‌بندی، فناوری‌های تولید و راهکارهای دیجیتال است. شرکت‌کنندگان می‌توانند با جدیدترین روندهای صنعت آشنا شوند.5. تقویت برند و افزایش اعتبار حرفه‌ایحضور در معتبرترین رویداد دارویی کشور، جایگاه برند را در میان فعالان صنعت ارتقا می‌دهد و نشان‌دهنده پویایی، توانمندی و حضور مؤثر شرکت در بازار است.6. شبکه‌سازی حرفه‌ای (Networking)در طول نمایشگاه فرصت ملاقات با تولیدکنندگان، تأمین‌کنندگان، شرکت‌های دانش‌بنیان، دانشگاه‌ها، مراکز تحقیقاتی و فعالان حوزه سلامت فراهم می‌شود که می‌تواند به همکاری‌های بلندمدت منجر شود.7. آشنایی با رقبا و تحلیل بازاربازدید از غرفه‌ها و گفت‌وگو با فعالان صنعت، تصویری دقیق از وضعیت بازار، روندهای آینده، محصولات جدید و استراتژی رقبا در اختیار شرکت‌ها قرار می‌دهد.8. بهره‌مندی از برنامه‌های علمی و تخصصیهمایش‌ها، نشست‌های تخصصی، کارگاه‌های آموزشی و پنل‌های علمی همزمان با نمایشگاه برگزار می‌شوند و امکان تبادل دانش و تجربه را برای متخصصان فراهم می‌کنند.9. فرصت جذب سرمایه و همکاری‌های فناورانهIRANPHARMA بستری برای معرفی طرح‌های نوآورانه، ایجاد مشارکت‌های فناورانه و جذب سرمایه در حوزه دارو و صنایع وابسته است.10. حضور در بزرگ‌ترین رویداد دارویی کشوراین نمایشگاه با حضور صدها شرکت داخلی و خارجی و هزاران بازدیدکننده تخصصی، مهم‌ترین گردهمایی صنعت داروسازی ایران محسوب می‌شود و نقش مهمی در توسعه این صنعت ایفا می‌کند.جمع‌بندیشرکت در IRANPHARMA تنها حضور در یک نمایشگاه نیست؛ بلکه فرصتی برای توسعه کسب‌وکار، افزایش فروش، گسترش شبکه ارتباطی، آشنایی با فناوری‌های نوین، ورود به بازارهای جدید و تثبیت جایگاه برند در صنعت داروسازی ایران و منطقه است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('F2ZZC2MO', 'اطلاعات', '- ابعاد و گستردگی نمایشگاه نمایشگاه ایران‌فارما چقدر است؟', '1. دسترسی مستقیم به تصمیم‌گیران صنعت دارودر نمایشگاه بین‌المللی ایران فارما مدیران عامل، مدیران فنی، مدیران خرید، مسئولان تأمین، سرمایه‌گذاران، نهادهای حاکمیتی و فعالان زنجیره تأمین دارو حضور دارند. این فرصت امکان مذاکرات مستقیم و ایجاد همکاری‌های جدید را فراهم می‌کند.2. توسعه بازار و جذب مشتریان جدیدنمایشگاه بستری ایده‌آل برای معرفی محصولات، خدمات و توانمندی‌های شرکت‌ها به مخاطبان تخصصی است. بسیاری از مذاکرات تجاری و قراردادهای همکاری از همین ارتباطات اولیه شکل می‌گیرند.3. فرصت‌های صادراتی و همکاری‌های بین‌المللیحضور شرکت‌ها، هیئت‌های تجاری و بازدیدکنندگان خارجی، فرصت مناسبی برای شناسایی بازارهای جدید،  صادرات و D26 همکاری‌های بین‌المللی فراهم می‌کند.4. معرفی نوآوری‌ها و فناوری‌های روزIRANPHARMA ویترینی از آخرین دستاوردهای صنعت داروسازی، بیوتکنولوژی، تجهیزات، مواد اولیه، بسته‌بندی، فناوری‌های تولید و راهکارهای دیجیتال است. شرکت‌کنندگان می‌توانند با جدیدترین روندهای صنعت آشنا شوند.5. تقویت برند و افزایش اعتبار حرفه‌ایحضور در معتبرترین رویداد دارویی کشور، جایگاه برند را در میان فعالان صنعت ارتقا می‌دهد و نشان‌دهنده پویایی، توانمندی و حضور مؤثر شرکت در بازار است.6. شبکه‌سازی حرفه‌ای (Networking)در طول نمایشگاه فرصت ملاقات با تولیدکنندگان، تأمین‌کنندگان، شرکت‌های دانش‌بنیان، دانشگاه‌ها، مراکز تحقیقاتی و فعالان حوزه سلامت فراهم می‌شود که می‌تواند به همکاری‌های بلندمدت منجر شود.7. آشنایی با رقبا و تحلیل بازاربازدید از غرفه‌ها و گفت‌وگو با فعالان صنعت، تصویری دقیق از وضعیت بازار، روندهای آینده، محصولات جدید و استراتژی رقبا در اختیار شرکت‌ها قرار می‌دهد.8. بهره‌مندی از برنامه‌های علمی و تخصصیهمایش‌ها، نشست‌های تخصصی، کارگاه‌های آموزشی و پنل‌های علمی همزمان با نمایشگاه برگزار می‌شوند و امکان تبادل دانش و تجربه را برای متخصصان فراهم می‌کنند.9. فرصت جذب سرمایه و همکاری‌های فناورانهIنمایشگاه بین‌المللی ایران فارما بستری برای معرفی طرح‌های نوآورانه، ایجاد مشارکت‌های فناورانه و جذب سرمایه در حوزه دارو و صنایع وابسته است.10. حضور در بزرگ‌ترین رویداد دارویی کشوراین نمایشگاه با حضور صدها شرکت داخلی و خارجی و هزاران بازدیدکننده تخصصی، مهم‌ترین گردهمایی صنعت داروسازی ایران محسوب می‌شود و نقش مهمی در توسعه این صنعت ایفا می‌کند.جمع‌بندیشرکت در نمایشگاه بین‌المللی ایران فارما  تنها حضور در یک نمایشگاه نیست؛ بلکه فرصتی برای توسعه کسب‌وکار، افزایش فروش، گسترش شبکه ارتباطی، آشنایی با فناوری‌های نوین، ورود به بازارهای جدید و تثبیت جایگاه برند در صنعت داروسازی ایران و منطقه است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('RGYAO39B', 'معرفی', 'ایران فارما استیج چیست؟', 'یکی از بخش‌های محتوایی و تعاملی نمایشگاه است که با هدف ارائه دانش، انتقال تجربه، معرفی نوآوری‌ها و ایجاد ارتباط میان فعالان صنعت داروسازی برگزار می‌شود.این فضا بستری برای سخنرانی‌ها، ارائه‌های تخصصی، معرفی فناوری‌های نوین، نشست‌های تخصصی، گفت‌وگوهای صنعتی و شبکه‌سازی میان مدیران، نشستهای حکمرانی صنعت دارو با حضور بازدیگران و تصمیمسازان و متخصصان، شرکت‌های دانش‌بنیان، سرمایه‌گذاران و فعالان حوزه سلامت است.استیج نمایشگاه بین‌المللی ایران فارما، صحنه اصلی تبادل دانش، فناوری، نوآوری و تجربه در بزرگ‌ترین گردهمایی صنعت داروسازی کشور است. واقع در سالن H نیم طبقه بالا و محل برگزاری مراسم افتتاحیه و پنل‌ها و سخنرانی‌هایی حول محور سیاست‌گذاری و مسائل کلان صنایع دارویی است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('GTR0KP2M', 'معرفی', 'ایران فارما کانکت چیست؟', 'فضای توسعه کسب و کار واقع در سالن H نیم طبقه بالا، محل برگزاری رویدادهای B2B و B2G و نشست‌های تخصصی در راستای ایجاد ارتباط میان بخش‌های مختلف زنجیره تامین و گسترش تعاملات بین‌المللی است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('VHTRWUZ6', 'معرفی', 'ایران فارما کست چیست؟', 'مرکز رسانه و خبری نمایشگاه است که خبرنگاران و اهالی رسانه امکان بهره‌برداری از آن را در سه روز نمایشگاه دارند و با هدف ثبت، تولید و انتشار گفتگوهای تخصصی صنعت داروسازی طراحی شده است.در ایران فارما کست، مدیران ارشد صنعت دارو، فعالان حوزه سلامت، متخصصان، پژوهشگران، کارآفرینان و چهره‌های تأثیرگذار این صنعت در قالب مصاحبه‌ها و گفتگوهای تخصصی، دیدگاه‌ها، تجربیات، چالش‌ها و فرصت‌های پیش روی صنعت داروسازی را مطرح می‌کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('XN4DJ9CP', 'معرفی', 'ایران فارما بریج چیست؟', 'فضای اختصاصی که یکی از بخش‌های ارتباطی و توسعه همکاری‌های نمایشگاه بین‌المللی ایران فارما است که با هدف ایجاد پل ارتباطی میان شرکت‌های دارویی، سرمایه‌گذاران، فناوران، شرکت‌های دانش‌بنیان، استارتاپ‌ها، هیئت‌های تجاری و شرکای بین‌المللی طراحی شده است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('FEJT6B14', 'معرفی', 'ایران فارما کمپس یا پردیس ایران فارما چیست؟', 'پاویون تعامل دانشجویان و صنعت واقع در نیم‌طبقه بالا شبستان H است. پردیس ایران فارما یکی از بخش‌های ویژه نمایشگاه بین‌المللی ایران فارما است که با هدف ارتقای مهارت دانشجویی و نزدیکی صنعت و دانشگاه طراحی شده است. پردیس ایران‌فارما محل برگزاری مسابقات و چالش‌های دانشجویی، المپیادهای صنعت و نشست‌های انتقال تجربه است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('9SH5Y06M', 'معرفی', 'ایران فارما لانژ چیست؟', 'مکانی برای برگزاری جلسات و دیدارهای کاری در روزهای برگزاری واقع در شبستان D است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ZEE045WL', 'اطلاعات، ثبت‌نام', 'چگونه ثبت‌نام کنم؟', 'ثبت‌نام بازدیدکنندگان در نمایشگاه بین‌المللی ایران فارما به‌صورت آنلاین انجام می‌شود.ثبت‌نام بازدیدکنندگانوارد وب‌سایت رسمی نمایشگاه شوید.بخش «ثبت‌نام بازدیدکنندگان» را انتخاب کنید.اطلاعات فردی و شغلی خود را تکمیل نمایید.پس از ثبت نهایی، کارت یا کد ورود برای شما صادر خواهد شد.در روز بازدید، کد QR  کارت مجازی  را در ورودی نمایشگاه ارائه کنید و با اسکن آن وارد می‌شوید. در دوره‌های گذشته این رویداد ثبت‌نام بازدیدکنندگان به‌صورت اینترنتی و پیش از آغاز نمایشگاه انجام شده است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('R1WN8VWW', 'اطلاعات', 'تفاوت نمایشگاه بین‌المللی ایران فارما و نمایشگاه فارمکس چیست؟', 'نمایشگاه بین‌المللی ایران فارما و نمایشگاه فارمکس هر دو از رویدادهای تخصصی حوزه داروسازی هستند، اما از نظر دامنه فعالیت، رویکرد، مخاطبان و جایگاه صنعتی تفاوت‌هایی با یکدیگر دارند.نمایشگاه بین‌المللی ایران فارما یک رویداد جامع و در سطح بین‌المللی در زنجیره صنعت داروسازی است که بخش‌های مختلف این صنعت را در کنار یکدیگر گرد هم می‌آورد. این نمایشگاه علاوه بر معرفی دارو و محصولات سلامت‌محور، حوزه‌هایی مانند مواد اولیه دارویی، تجهیزات و ماشین‌آلات داروسازی، فناوری‌های نوین، زیست‌فناوری، شرکت‌های دانش‌بنیان، خدمات تخصصی، تحقیق و توسعه، نوآوری و فرصت‌های سرمایه‌گذاری و تجاری را پوشش می‌دهد. همچنین با برگزاری برنامه‌های علمی، نشست‌های تخصصی، رویدادهای شبکه‌سازی، جلسات B2B و بخش‌های فناورانه، بستری برای تعامل میان صنعت، دانشگاه، سرمایه‌گذاران و فعالان داخلی و بین‌المللی فراهم می‌کند.در مقابل، نمایشگاه فارمکس تمرکز بر بخش مواد اولیه دارویی و خدمات بسته ‌بندی دارد و دامنه موضوعی محدودتری نسبت به یک رویداد جامع صنعت داروسازی دارد.از نظر ابعاد، تنوع مشارکت‌کنندگان و گستره مخاطبان نیز نمایشگاه بین‌المللی ایران فارما به دلیل پوشش بخش‌های مختلف زنجیره دارو، حضور طیف گسترده‌تری از شرکت‌های دارویی، مجموعه‌های دانش‌بنیان، متخصصان، مدیران صنعت، هیئت‌های تجاری و فعالان حوزه سلامت، جایگاه گسترده‌تری در اکوسیستم داروسازی دارد.به طور کلی می‌توان گفت نمایشگاه بین‌المللی ایران فارما نماینده یک نگاه جامع به صنعت داروسازی است و تمامی حلقه‌های زنجیره دارو را از تولید و فناوری تا تجارت، آموزش و نوآوری در کنار هم قرار می‌دهد؛ در حالی که نمایشگاه فارمکس تمرکز محدودتری بر بخش مواد اولیه دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('AZVFUH4F', 'اطلاعات', 'آیا یک استارتاپ می‌تواند مشتری یا شریک تجاری جدید پیدا کند؟', 'بله. نمایشگاه بین‌المللی ایران فارما محل حضور شرکت‌های مختلف زنجیره دارو است و استارتاپ‌ها می‌توانند با شناسایی نیازهای بازار، فرصت‌های همکاری تجاری، فروش فناوری، ارائه خدمات یا مشارکت‌های جدید پیدا کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('K7D886FS', 'اطلاعات', 'مهم‌ترین چیزی که یک استارتاپ باید قبل از حضور در نمایشگاه آماده کند چیست؟', 'یک معرفی حرفه‌ای از کسب‌وکار، توضیح واضح درباره مسئله‌ای که حل می‌کند، مزیت رقابتی، نمونه محصول یا نمونه اولیه، اطلاعات تماس، و برنامه مشخص برای ملاقات با شرکت‌ها و سرمایه‌گذاران.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('1UGDE0KT', 'اطلاعات', 'استارتاپ من هنوز محصول نهایی ندارد؛ آیا حضور در نمایشگاه برای من مفید است؟', 'بله. حتی در مراحل اولیه، حضور در نمایشگاه می‌تواند به شناخت بهتر نیازهای بازار، دریافت بازخورد از متخصصان، پیدا کردن شریک صنعتی، توسعه ارتباطات و اصلاح مسیر محصول کمک کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ROXKFFLD', 'اطلاعات', 'آیا بخش خاصی برای استارتاپ‌ها و شرکت‌های نوآور در نمایشگاه بین‌المللی ایران فارما وجود دارد؟', 'بله. تا دوره گذشته این رویداد بخش ایران‌فارما بریج ما با تمرکز بر نوآوری، فناوری و شرکت‌های دانش‌بنیان، فضایی برای معرفی ایده‌ها و دستاوردهای فناورانه و ایجاد ارتباط میان استارتاپ‌ها، صنعت و سرمایه‌گذاران فراهم می‌کند و برای اطلاعات بیشتر این بخش می توانید با دبیرخانه تماس بگیرید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('FOM0GLON', 'اطلاعات', 'آیا حضور در نمایشگاه بین‌المللی ایران فارما می‌تواند به جذب سرمایه کمک کند؟', 'بله. حضور سرمایه‌گذاران داخلی و خارجی، شرکت‌های بزرگ، نهادهای مالی، نهادهای تصمیم‌ساز و مجموعه‌های فناور و فعالان صنعت در نمایشگاه، فرصت مناسبی برای معرفی مدل کسب‌وکار، ارائه توانمندی‌ها و مذاکره برای جذب سرمایه یا ایجاد همکاری‌های مشترک فراهم می‌کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('GRY6IJ7J', 'اطلاعات', 'آیا نمایشگاه بین‌المللی ایران فارما برای استارتاپ‌های حوزه سلامت و دارو مناسب است؟', 'بله. این نمایشگاه بستری تخصصی برای معرفی استارتاپ‌هایی است که در حوزه‌هایی مانند فناوری سلامت، داروسازی، زیست‌فناوری، سلامت دیجیتال، هوش مصنوعی در سلامت، تحقیق و توسعه و راهکارهای نوآورانه فعالیت می‌کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('16ZGZZ09', 'اطلاعات', 'آیا امکان دریافت راهنمای نمایشگاه به صورت آنلاین وجود دارد؟', 'بله، فایل های قابل دانلود در صفحه مستندات وبسایت بارگذاری می شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('DETFSP1Z', 'اطلاعات', 'چرا نمایشگاه بین‌المللی ایران فارما برای جامعه داروسازی اهمیت دارد؟', 'زیرا این رویداد محلی برای اتصال دانش، تجربه، فناوری و صنعت است و به داروسازان امکان می‌دهد در جریان جدیدترین تحولات صنعت داروسازی قرار بگیرند و ارتباط مؤثرتری با اکوسیستم حرفه‌ای خود برقرار کنند. از طرفی در نمایشگاه بین‌المللی ایران‌فارما تمام حلقه‌های زنجیره تامین و تولید دارو رو می‌توان به صورت منسجم دید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('9X3EM5DN', 'اطلاعات', 'به عنوان یک استارتاپ، چرا باید در نمایشگاه بین‌المللی ایران فارما حضور داشته باشم؟', 'نمایشگاه بین‌المللی ایران فارما فرصتی ارزشمند برای استارتاپ‌هاست تا ایده، محصول یا فناوری خود را به بازیگران اصلی صنعت داروسازی معرفی کنند. این رویداد امکان ارتباط مستقیم با شرکت‌های دارویی، سرمایه‌گذاران، شرکت‌های دانش‌بنیان، مراکز تحقیقاتی و فعالان بازار را فراهم می‌کند و می‌تواند مسیر توسعه، تجاری‌سازی و رشد کسب‌وکار را هموار کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ZAVO4K0Z', 'اطلاعات', 'یک داروساز چگونه می‌تواند بیشترین بهره را از بازدید نمایشگاه بین‌المللی ایران فارما ببرد؟', 'با برنامه‌ریزی پیش از حضور، شناسایی شرکت‌ها و حوزه‌های مورد علاقه، شرکت در برنامه‌های علمی، گفت‌وگو با متخصصان و استفاده از فرصت‌های شبکه‌سازی می‌تواند تجربه‌ای ارزشمند و کاربردی از نمایشگاه داشته باشد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('JHX4QP50', 'اطلاعات', 'تفاوت نمایشگاه بین‌المللی ایران فارما با یک همایش علمی برای داروسازان چیست؟', 'همایش‌ها معمولاً تمرکز بیشتری بر ارائه علمی و انتقال دانش دارند؛ اما نمایشگاه بین‌المللی ایران فارما علاوه بر بخش علمی، امکان مشاهده مستقیم محصولات، ارتباط با شرکت‌ها، شناخت بازار، مذاکره و ایجاد همکاری‌های عملی را نیز فراهم می‌کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('CDY3PHIB', 'اطلاعات', 'نمایشگاه بین‌المللی ایران فارما چه ارتباطی با فعالیت حرفه‌ای داروسازان دارد؟', 'این نمایشگاه تمامی بخش‌های مرتبط با صنعت دارو از تولید و تحقیق و توسعه تا فناوری، تجهیزات، مواد اولیه و خدمات تخصصی را پوشش می‌دهد. حضور در آن به داروسازان کمک می‌کند شناخت بهتری از مسیر تولید دارو، نوآوری‌های صنعت و تغییرات آینده حوزه دارویی پیدا کنند. به عقیده کارشناسان این رویداد در تقویم داروسازان جایگاه ویژه ای دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('9UQ8ZU5I', 'اطلاعات', 'آیا داروسازان می‌توانند در نمایشگاه بین‌المللی ایران فارما فرصت‌های همکاری پیدا کنند؟', 'بله. این نمایشگاه محیطی مناسب برای شناسایی فرصت‌های همکاری در حوزه‌هایی مانند تحقیق و توسعه، آموزش، پروژه‌های علمی، همکاری با شرکت‌های دارویی، فعالیت‌های تخصصی و مسیرهای جدید حرفه‌ای است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('N5OJBT7S', 'اطلاعات', 'حضور در نمایشگاه بین‌المللی ایران فارما چه کمکی به توسعه دانش حرفه‌ای داروسازان می‌کند؟', 'شرکت در نشست‌های تخصصی، ارائه‌های علمی و گفتگو با متخصصان صنعت، امکان آشنایی با چالش‌ها، روندهای آینده، تجربیات مدیریتی و علمی و تحولات جدید حوزه داروسازی را فراهم می‌کند', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('4ZROBBE7', 'اطلاعات', 'آیا نمایشگاه بین‌المللی ایران فارما برای آشنایی با داروهای جدید و فناوری‌های نوین مناسب است؟', 'بله. این نمایشگاه بستری برای معرفی جدیدترین محصولات، فناوری‌های تولید، دستاوردهای تحقیقاتی، حوزه‌های نوین مانند زیست‌فناوری، داروهای پیشرفته و راهکارهای جدید در صنعت داروسازی است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('SA99YPPJ', 'اطلاعات', 'یک داروساز چه فرصت‌هایی برای شبکه‌سازی در نمایشگاه بین‌المللی ایران فارما دارد؟', 'داروسازان می‌توانند با مدیران و کارشناسان شرکت‌های دارویی، پژوهشگران، متخصصان حوزه سلامت و سایر فعالان صنعت ارتباط برقرار کنند، تجربیات خود را به اشتراک بگذارند و فرصت‌های همکاری علمی، پژوهشی یا حرفه‌ای ایجاد کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('05PUCWA7', 'اطلاعات', 'آیا نمایشگاه بین‌المللی ایران فارما فقط برای مدیران شرکت‌های دارویی است؟', 'خیر. این نمایشگاه برای تمام فعالان حوزه دارو از جمله داروسازان، متخصصان، پژوهشگران، اعضای هیئت علمی، دانشجویان و کارشناسان صنعت سلامت طراحی شده است و هر گروه می‌تواند متناسب با نیاز خود از آن بهره ببرد. مدیران و کارشناسان واحدهای مختلف تولید، کنترل کیفیت، تضمین کیفیت، انبار، بازرگانی و بازاریابی، تحقیق و توسعه و رگولاتورری  و ... در نمایشگاه ایران‌فارما حضور بهم می‌رسانند و از آن دیدار می‌کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ABW0WYZN', 'اطلاعات، ثبت‌نام', 'به عنوان یک داروساز، چرا باید از نمایشگاه بین‌المللی ایران فارما بازدید کنم؟', 'نمایشگاه بین‌المللی ایران فارما فرصتی برای آشنایی با جدیدترین محصولات، فناوری‌ها، دستاوردهای علمی و روندهای روز صنعت داروسازی است. داروسازان می‌توانند با شرکت‌های تولیدکننده، تأمین‌کنندگان، متخصصان و فعالان زنجیره دارو ارتباط برقرار کرده و از فرصت‌های علمی، حرفه‌ای و تجاری این رویداد بهره‌مند شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('54AMOG9V', 'اطلاعات', 'آیا شرکت‌های دانش‌بنیان حضور دارند؟', 'بله، شرکت‌های دانش‌بنیان در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('5050SJKL', 'اطلاعات', 'چه خدماتی برای غرفه‌داران نمایشگاه بین‌المللی ایران فارما ارائه می‌شود؟', 'غرفه‌داران میتوانند از خدماتی مانند تخصیص فضای نمایشگاهی، برنامه‌ریزی حضور، پشتیبانی اجرایی، معرفی شرکت در بسترهای اطلاع‌رسانی نمایشگاه، دسترسی به مخاطبان تخصصی، فرصت برگزاری جلسات تجاری و حضور در برنامه‌های جانبی نمایشگاه بهره‌مند می‌شوند که نیازمند هماهنگی با بخش مارکتینگ نمایشگاه است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('974P9E13', 'اطلاعات، ثبت‌نام', 'مدارک لازم برای ثبت‌نام چیست؟', 'اطلاعات کاربری، شماره تلفن همراه یا آدرس پست الکترونیکی', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('GX2FK8TZ', 'اطلاعات', 'آیا نمایشگاه بین‌المللی ایران فارما خدمات تبلیغاتی برای شرکت‌ها دارد؟', 'بله. شرکت‌ها می‌توانند از فرصت‌های تبلیغاتی و برندینگ نمایشگاه برای افزایش دیده‌شدن، معرفی محصولات و خدمات، حضور در رسانه‌ها، معرفی در کانال‌های اطلاع‌رسانی و تقویت جایگاه برند خود استفاده کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('G1TCA192', 'اطلاعات، ثبت‌نام', 'آیا ثبت‌نام آنلاین امکان‌پذیر است؟', 'ثبت‌نام تنها به صورت آنلاین انجام می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('CQQ7EQO7', 'اطلاعات، ثبت‌نام', 'آیا ثبت‌نام در محل امکان دارد؟', 'بله، می‌توانید با استفاده از کیوسک‌های لمسی مستقر و یا با استفاده از تلفن همراه خود و اسکن QR کدهای موجود در ورودی نمایشگاه و با همراهی و راهنمایی کارکنان دبیرخانه، در محل ثبت‌نام کنید. اما ثبت نام در روزهای قبل از رویداد و از طریق پلتفرم این رویداد توصیه می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('VMHS73WP', 'اطلاعات، ثبت‌نام', 'کارت ورود چگونه دریافت می‌شود؟', 'کارت ورود بازدیدکنندگان به صورت یک لینک و تصویر به تلفن همراه ثبت‌نام‌کننده ارسال می‌شود. همچنین تصویر کار در پروفایل کاربر قابل رویت خواهد بود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('O74AJSLD', 'اطلاعات، ثبت‌نام', 'آیا کارت ورود قابل انتقال است؟', 'خیر، کارت ورود هر فرد برای شماره همراه ایشان ارسال می‌شود و تنها در پروفایل شخص قابل مشاهده است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('SXKYNVUT', 'اطلاعات، ثبت‌نام', 'در صورت گم شدن کارت چه باید کرد؟', 'می‌توانید با مراجعه به پروفایل خود در سایت نمایشگاه به نسخه دیجیتال کارت خود دسترسی پیدا کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('N6J8AVUX', 'اطلاعات، ثبت‌نام', 'آیا دانشجویان می‌توانند ثبت‌نام کنند؟', 'بله، دانشجویان می‌توانند با مراجعه به وبسایت در نمایشگاه ثبت‌نام کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('21XDNPC8', 'اطلاعات، ثبت‌نام', 'آیا پزشکان مزایای ویژه دارند؟', 'پزشکان می‌توانند با ثبت‌نام در برنامه‌های جانبی از مطالب ارائه‌شده بهره‌مند شده و در پایان گواهی الکترونیکی شرکت در برنامه را از طریق پروفایل خود دریافت کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('9XFQFQLF', 'اطلاعات، ثبت‌نام', 'آیا داروسازان نیاز به مدرک دارند؟', 'خیر، نیازی به ارائه مدرک نیست.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('RPSCQLC7', 'اطلاعات، ثبت‌نام', 'آیا ثبت‌نام رایگان است؟', 'بله، ثبت‌نام برای بازدید از نمایشگاه آزاد و رایگان است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('WJQ5IKJ7', 'اطلاعات', 'آیا کودکان اجازه ورود دارند؟', 'بله، کودکان می‌توانند وارد فضای نمایشگاه شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('MOYKWOKC', 'اطلاعات', 'آیا محدودیت سنی وجود دارد؟', 'خیر، نمایشگاه محدودیت سنی ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('351N96G9', 'اطلاعات، ثبت‌نام', 'آیا امکان ویرایش اطلاعات ثبت‌نام وجود دارد؟', 'بله، امکان ویرایش اطلاعات ثبت‌نام در پروفایل کاربران وجود دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('97XAXQLQ', 'اطلاعات، ثبت‌نام', 'آیا ایمیل تأیید ارسال می‌شود؟', 'در صورت ثبت‌نام از طریق ایمیل، بله ارسال می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('XQ5LDY6T', 'اطلاعات، ثبت‌نام', 'اگر پیامک تأیید دریافت نکنم چه کنم؟', 'می‌توانید چند دقیقه بعد مجدداً امتحان نمایید و یا از طریق ایمیل ثبت نام کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('6SCPM2HZ', 'اطلاعات، ثبت‌نام', 'آیا امکان لغو ثبت‌نام وجود دارد؟', 'خیر، امکان لغو ثبت‌نام در نمایشگاه یا برنامه‌های جانبی وجود ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('BGF6CZ5F', 'اطلاعات، ثبت‌نام', 'آیا ثبت‌نام سازمانی امکان‌پذیر است؟', 'خیر، مشارکت‌کنندگان می‌بایست به صورت جداگانه ثبت‌نام کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('9ULYTUWK', 'اطلاعات، ثبت‌نام', 'آیا ثبت‌نام گروهی تخفیف دارد؟', 'برای اطلاع از تخفیف گروهی ثبت‌نام در برنامه‌های جانبی می‌توانید با دبیرخانه تماس بگیرید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('K5CM8UF4', 'اطلاعات، ثبت‌نام', 'آیا یک کارت ورود برای بازدید از تمامی سالن‌ها کافی است؟', 'بله، کارت بازدیدکننده امکان دسترسی به تمامی بخش‌های عمومی نمایشگاه را فراهم می‌کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('PS55WIJ3', 'اطلاعات، ثبت‌نام', 'آیا حضور در نشست‌ها و همایش‌های تخصصی شامل ثبت‌نام می‌شود؟', 'بسته به نوع برنامه و شرایط ثبت‌نام، ممکن است نیاز به ثبت‌نام جداگانه باشد. با مراجعه به وبسایت نمایشگاه می توانید از جزییات برنامه ها و چگونگی ثبت نام در آن ها مطلع شوید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('UBV2EUAC', 'اطلاعات، ثبت‌نام', 'برای ورود به نمایشگاه چه مدارکی لازم است؟', 'کافی است تصویر کارت مجازی خود را از لینک ارسال شده به تلفن همراه خود در ورودی نمایشگاه نشان دهید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('41US3VWJ', 'اطلاعات، رویداد‌های جانبی', 'آیا امکان برگزاری جلسات B2B وجود دارد؟', 'بله، برنامه‌های ویژه‌ای برای جلسات تجاری و شبکه‌سازی در نظر گرفته شده است که جزییات آن از طریق شبکه های مجازی رویداد اطلاع رسانی می شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('CNCECC05', 'اطلاعات، خدمات', 'کدام هتل ها در نزدیکی محل برگزاری قرار دارند؟', 'هتل های پرشین پلازا و ونوس واقع در خیابان سهروردی شمالی، هتل های سیمرغ و رامتین واقع در خیابان ولیعصر، و هتل های بزرگ تهران و ساینا واقع در خیابان شهید مطهری از جمله نزدیک ترین هتل ها به محل برگزاری نمایشگاه هستند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('C2XZRUGQ', 'اطلاعات، خدمات', 'آیا امکانات پذیرایی در نمایشگاه وجود دارد؟', 'بله، رستوران‌ها، کافی‌شاپ‌ها و بخش‌های پذیرایی در حیاط یاس برای مشارکت کنندگان و بازدیدکنندگان فراهم است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('RRJ7VX8H', 'اطلاعات، برنامه‌های جانبی', 'چه فرصت‌های شبکه‌سازی در نمایشگاه وجود دارد؟', 'جلسات B2B، نشست‌های تخصصی، رویدادهای جانبی و فرصت‌های ارتباط مستقیم با فعالان صنعت.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('835W1LEB', 'اطلاعات، برنامه‌های جانبی', 'آیا سرمایه‌گذاران می‌توانند در نمایشگاه حضور داشته باشند؟', 'بله، سرمایه‌گذاران حوزه سلامت و داروسازی از مخاطبان مهم نمایشگاه هستند و می توانند با حضور در فضاهای ویژه نمایشگاه با آخرین فرصت های سرمایه گذاری در صنعت آشنا شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('3W03RQB5', 'اطلاعات', 'آیا نمایشگاه برای یافتن شرکای تجاری مناسب است؟', 'بله، بسیاری از شرکت‌ها برای توسعه همکاری‌ها و قراردادهای جدید در این رویداد شرکت می‌کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('J7CAK942', 'اطلاعات، خدمات', 'آیا امکان ارتباط مستقیم با تولیدکنندگان دارو وجود دارد؟', 'بله، بازدیدکنندگان می‌توانند مستقیماً با تولیدکنندگان و مدیران شرکت‌ها ملاقات کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('M8IIR9B4', 'اطلاعات، خدمات', 'آیا سازمان‌های دولتی و نهادهای نظارتی در نمایشگاه حضور دارند؟', 'بله، نهادهای مرتبط با حوزه سلامت و داروسازی از جمله نمایندگان وزارت بهداشت، سازمان غذا و دارو و سندیکای صاحبان صنایع داروهای انسانی ایران، نمایندگانی معاونت های مربوطه در وزارت صنعت، و کارشناسان أمور مربوط به بانک مرکزی در نمایشگاه مشارکت دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('A3974AV4', 'اطلاعات، ثبت‌نام', 'آیا خبرنگاران می‌توانند در نمایشگاه حضور داشته باشند؟', 'بله، خبرنگاران و رسانه‌های تخصصی می‌توانند پس از دریافت مجوز رسانه‌ای در نمایشگاه شرکت کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('T52E61BR', 'اطلاعات، ثبت‌نام', 'چگونه می‌توان برای دریافت کارت رسانه‌ای اقدام کرد؟', 'از طریق بخش ثبت‌نام رسانه‌ها در وب‌سایت رسمی نمایشگاه.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('KLS8WPUC', 'اطلاعات', 'آیا آمار و گزارش نمایشگاه منتشر می‌شود؟', 'بله، گزارش نهایی و آمار مشارکت‌کنندگان پس از پایان نمایشگاه منتشر می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('2RHSXPGQ', 'اطلاعات، ثبت‌نام', 'چگونه از اخبار دوره‌های آینده مطلع شوم؟', 'با عضویت در خبرنامه و دنبال کردن کانال‌های رسمی نمایشگاه.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ET884FN4', 'اطلاعات، ثبت‌نام', 'آیا امکان پیش‌ثبت‌نام برای دوره بعدی وجود دارد؟', 'بله، پس از پایان هر دوره امکان پیش‌ثبت‌نام فراهم می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('85RWC996', 'اطلاعات', 'چگونه می‌توان به اطلاعات غرفه‌داران دسترسی داشت؟', 'از طریق تهیه دایرکتوری شرکت‌کنندگان و وب‌سایت نمایشگاه.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('9DPXU73P', 'اطلاعات، غرفه‌داران', 'چگونه می‌توان با تیم IPH Expo تماس گرفت؟', 'از طریق فرم تماس، ایمیل یا شماره‌های ارتباطی درج‌شده در وب‌سایت رسمی نمایشگاه.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('BMRTLVGN', 'اطلاعات، غرفه‌داران', 'چگونه غرفه رزرو کنیم؟', 'برای رزرو غرفه باید پس از ساخت پروفایل شرکت در سایت نمایشگاه، ساعت 9:00 روز 24 خرداد به پروفایل شرکت مراجعه کرده و غرفه مورد نظر خود را انتخاب کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('4UTV06IM', 'اطلاعات، غرفه‌داران', 'هزینه غرفه چقدر است؟', 'برای اطلاع از هزینه غرفه می‌توانید با دبیرخانه نمایشگاه تماس حاصل نمایید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('KC011NMP', 'اطلاعات، غرفه‌داران', 'حداقل متراژ غرفه چیست؟', 'حداقل متراژ غرفه 12 متر مربع است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('8QJYRKQF', 'اطلاعات، غرفه‌داران', 'آیا غرفه خام ارائه می‌شود؟', 'بله، امکان دریافت غرفه خام وجود دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('GLEP6HGD', 'اطلاعات، غرفه‌داران', 'آیا غرفه آماده ارائه می‌شود؟', 'در صورت انتخاب خدمات غرفه‌سازی پیش‌ساخته امکان ارائه غرفه آماده وجود دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('74VK5ZDH', 'اطلاعات، غرفه‌داران', 'شرایط پرداخت چیست؟', 'پرداخت به صورت کامل پس از صدور پیش‌فاکتور و در مهلت مقرر.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('DNH4FBDT', 'اطلاعات، غرفه‌داران', 'مهلت ثبت‌نام غرفه‌داران چه زمانی است؟', 'ثبت‌نام و جانمایی غرفه‌داران از تاریخ اعلام شده تا زمان تکمیل فضاهای قابل رزرو ادامه خواهد داشت.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('HT0ZVN4V', 'اطلاعات، غرفه‌داران', 'آیا شرکت‌های خارجی می‌توانند در پاویون‌های ملی شرکت کنند؟', 'شرکت‌هایی که در کشورهای چین، هند، و ترکیه فعالیت می‌کنند، می‌توانند با مراجعه به بخش تماس با ما در وبسایت نمایشگاه، نسبت به رزرو غرفه از طریق تماس با نماینده دبیرخانه در آن کشور اقدام کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('XZZWG7P7', 'اطلاعات، غرفه‌داران', 'آیا امکان انتخاب سالن وجود دارد؟', 'سالن نمایشگاهی یکپارچه است و تقسیم‌بندی‌های روی نقشه به صورت نمادین بخش‌های مختلف نمایشگاه را تفکیک می‌کند. شرکت‌ها و حامیان، بر اساس محدودیت‌های جانمایی، می‌توانند از میان شبستان‌های موجود، مکان مورد نظر خودشان را انتخاب کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('1ONHXN68', 'اطلاعات، غرفه‌داران', 'نحوه جانمایی غرفه‌ها چگونه است؟', 'شرکت‌های تولیدکننده می‌توانند در زمان اعلام شده برای جانمایی، از طریق پنل شرکت در وبسایت نمایشگاه، غرفه مورد نظر خود را انتخاب کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('VOJJXO5L', 'اطلاعات، غرفه‌داران', 'آیا برق سه‌فاز ارائه می‌شود؟', 'شرکت‌ها می‌توانند با تکمیل فرم خدمات نمایشگاهی درخواست خود را برای تامین برق سه‌فاز در روزهای نمایشگاه ثبت کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('DE6UEYEY', 'اطلاعات، غرفه‌داران', 'آیا اینترنت اختصاصی قابل سفارش است؟', 'خیر، امکان ارائه اینترنت اختصاصی وجود ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('WEU4Z9K2', 'اطلاعات، غرفه‌داران', 'آیا انبار در اختیار غرفه‌داران قرار می‌گیرد؟', 'خیر، فضای انباری مجزا از غرفه‌ها برای استفاده غرفه‌داران وجود ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('Y1N98HOY', 'اطلاعات، غرفه‌داران', 'ساعت ورود غرفه‌داران چیست؟', 'غرفه‌داران می‌توانند ساعت 8:30 صبح برای آماده‌سازی و چیدمان در نمایشگاه حاضر شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('N2FR89C0', 'اطلاعات، غرفه‌داران', 'ساعت تخلیه غرفه چیست؟', 'سالن نمایشگاه می‌بایست تا ساعت 17:30 تخلیه شده و تا صبح روز آینده مهر و موم شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('L073PQKC', 'اطلاعات، غرفه‌داران', 'قوانین ساخت غرفه چیست؟', 'قوانین غرفه‌سازی در بخش مستندات وبسایت نمایشگاه قابل دریافت است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('M6NHLTZ5', 'اطلاعات، غرفه‌داران', 'آیا پیمانکار غرفه‌سازی معرفی می‌شود؟', 'پیمانکار غرفه‌سازی بر اساس مقررات منتشر شده و مهلت‌های اعلام شده در متن فایل مقررات باید معرفی شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ZU9HACIE', 'اطلاعات، غرفه‌داران', 'آیا امکان تبلیغات محیطی وجود دارد؟', 'بله، شرکت‌ها می‌توانند با تماس با دبیرخانه از تبلیغات محیطی آگاه شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('PFN3HZJW', 'اطلاعات، غرفه‌داران', 'آیا امکان نصب نمایشگر بزرگ وجود دارد؟', 'شرکت‌ها می‌توانند در غرفه‌های خود از نمایشگرهای بزرگ استفاده کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('WG8X50VG', 'اطلاعات، غرفه‌داران', 'آیا خدمات نظافت ارائه می‌شود؟', 'راهروها و فضاهای عمومی نمایشگاه به صورت مداوم نظافت می‌شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('7AEG1UOF', 'اطلاعات، غرفه‌داران', 'آیا امنیت غرفه‌ها تأمین می‌شود؟', 'امنیت غرفه‌ها از زمان تخلیه سالن در مهلت غرفه‌سازی و چیدمان، تا پیش از ورود غرفه‌داران در صبح روز اول، و بعد از آن از ساعت پایان هر روز نمایشگاه تا ساعت ورود غرفه‌داران در روز بعد از آن توسط دبیرخانه تامین می‌شود. در دیگر زمان‌ها توصیه می‌شود که غرفه‌دران اقدامات لازم را جهت تامین امنیت غرفه‌ها و اقلام باارزش انجام دهند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('BSXM6IEA', 'اطلاعات، غرفه‌داران', 'آیا بیمه غرفه لازم است؟', 'بله، شرکت‌ها می‌بایست مشارکت خود را در نمایشگاه بیمه کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('I0FL6EY2', 'اطلاعات، غرفه‌داران', 'آیا امکان انتقال غرفه وجود دارد؟', 'شرکت‌ها پس از جانمایی، در هیچ مرحله‌ای، راساً امکان انتقال غرفه خود را نخواهند داشت. در صورت عدم تمایل به مشارکت در نمایشگاه، شرکت‌ها می‌بایست این موضوع را به صورت یک نامه رسمی به دبیرخانه اعلام نمایند، تا غرفه انتخاب شده توسط شرکت آزاد شده و بر اساس فهرست انتظار دبیرخانه، مجدداً جانمایی شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('45Y8ZPP5', 'اطلاعات، غرفه‌داران', 'آیا امکان افزایش متراژ وجود دارد؟', 'ابعاد فضاهای تقسیم‌بندی شده بر اساس محدودیت‌های فنی مشخص شده و امکان تغییر هیچ یک از غرفه‌ها وجود ندارد. شرکت‌ها می‌توانند در صورت آزاد شدن فضاهای مجاور، در صورت امکان و با در نظر داشتن محدودیت‌های قوانین و مقررات نمایشگاه، فضای آزاد شده را به غرفه خود اضافه کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('T4O7OMNC', 'اطلاعات، غرفه‌داران', 'نحوه دریافت فاکتور چیست؟', 'پس از تایید جانمایی، پیش‌فاکتور برای شرکت‌ها صادر و به صورت الکترونیکی ارسال می‌شود. شرکت‌ها می‌توانند در صورت نیاز با هماهنگی با دبیرخانه، جهت دریافت نسخه چاپ شده پیش‌فاکتور به دبیرخانه مراجعه کنند. فاکتور نمایشگاه، پس از برگزاری برای شرکت‌کنندگان ارسال خواهد شد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('PBYV1NY7', 'اطلاعات، غرفه‌داران', 'شرایط انصراف چیست؟', 'مبالغ پرداخت شده پس از تایید جانمایی و صدور پیش‌فاکتور غیرقابل عودت بوده و شرکت‌ها در صورت تمایل به انصراف می‌بایست این موضوع را به صورت کتبی به دبیرخانه اطلاع دهند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('NEVBGWW7', 'اطلاعات، غرفه‌داران', 'آیا شرکت‌های خارجی می‌توانند مستقیماً غرفه بگیرند؟', 'شرکت‌های خارجی می‌توانند با ارسال ایمیل به دبیرخانه info@iphexpo.com برای رزرو غرفه اقدام کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('9TPZT0PX', 'اطلاعات', 'آیا استارتاپ‌های سلامت حضور دارند؟', 'بله، استارتاپ‌های سلامت در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('LFDHCC17', 'اطلاعات، غرفه‌داران', 'آیا شرکت‌های خارجی می‌توانند از طریق شرکت‌های ایرانی در نمایشگاه حضور داشته باشند؟', 'در صورت داشتن قرارداد رسمی با شرکت‌های ایرانی، امکان حضور به عنوان نماینده در نمایشگاه وجود دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('XH9MVQ1M', 'اطلاعات، غرفه‌داران', 'نحوه ارسال تجهیزات چگونه است؟', 'شرکت‌های خارجی می‌توانند با هماهنگی دبیرخانه نسبت به ارسال و ترخیص تجهیزات ارسالی خود اقدام کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('WPE9J3C2', 'اطلاعات، خدمات', 'آیا خدمات حمل‌ونقل وجود دارد؟', 'شاتل‌های دبیرخانه در روزهای آماده‌سازی و نمایشگاه به صورت مداوم برای تسهیل جابه‌جایی مشارکت‌کنندگان از ورودی‌های اصلی مصلا، واقع در خیابان شهید بهشتی و ورودی متروی مصلا تا ورودی شبستان فعال هستند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('8CMVMTY3', 'اطلاعات، غرفه‌داران', 'آیا غرفه‌داران کتاب نمایشگاه را دریافت می‌کنند؟', 'یک نسخه از کتاب نمایشگاه، حاوی نام و اطلاعات تمام شرکت‌های حاضر در نمایشگاه، به صورت رایگان دریافت می‌کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('DUPIVO9F', 'اطلاعات، غرفه‌داران', 'آیا امکان تهیه کتاب نمایشگاه وجود دارد؟', 'مشارکت‌کنندگان می‌توانند با مراجعه به ستون اطلاعات نمایشگاه، کتاب نمایشگاه را تهیه کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('59VR7XRF', 'اطلاعات، غرفه‌داران', 'چه اقلامی در غرفه ممنوع هستند؟', 'چه اقلامی در غرفه ممنوع هستند؟', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('0UIT24UD', 'اطلاعات، غرفه‌داران', 'چه شرکت‌هایی می‌توانند در نمایشگاه حضور داشته باشند؟', 'شرکت‌های دارویی، تولیدکنندگان مواد اولیه، شرکت‌های بیوتکنولوژی، تجهیزات آزمایشگاهی، بسته‌بندی، فناوری سلامت و صنایع مرتبط.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('7KNLVHSM', 'اطلاعات، غرفه‌داران', 'غرفه های پیش ساخته شامل چه امکاناتی هستند؟', 'فضای نمایشگاهی، پنل بندی، روشنایی، کتیبه، و برای هر دوازده متر، یک میز و دو صندلی نمایشگاهی', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('VTWFA18Y', 'اطلاعات، غرفه‌داران', 'آیا امکان طراحی اختصاصی غرفه وجود دارد؟', 'بله، شرکت‌ها می‌توانند غرفه‌های خود را مطابق با ضوابط نمایشگاه و با هماهنگی واحد خدمات نمایشگاهی در مهلت های معین شده طراحی و اجرا کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('VO575T1E', 'اطلاعات، غرفه‌داران', 'آیا استارتاپ‌ها می‌توانند در نمایشگاه حضور داشته باشند؟', 'بله، استارتاپ‌های فعال در حوزه سلامت و داروسازی می توانند با هماهنگی دبیرخانه از فضای اختصاصی در پاویون ایران فارما بریج بهره مند شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('4U91W3LR', 'اطلاعات، غرفه‌داران', 'آیا نمایشگاه از غرفه‌داران حمایت تبلیغاتی می‌کند؟', 'بله، شرکت‌ها از طریق وب‌سایت، کاتالوگ و کتاب نمایشگاه معرفی می‌شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('Z15HYP0R', 'اطلاعات، غرفه‌داران', 'آیا برای غرفه‌داران کارت ورود صادر می‌شود؟', 'بله، بر اساس متراژ و نوع مشارکت، کارت‌های ورود اختصاصی ارائه می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('Q4OA6H7O', 'اطلاعات، غرفه‌داران', 'آیا برای دریافت ویزا نامه دعوت صادر می‌شود؟', 'در صورت نیاز و پس از ثبت‌نام، نامه دعوت و خدمات صدور ویزا برای شرکت‌کنندگان واجد شرایط ارایه می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('35OP7MPR', 'اطلاعات، غرفه‌داران', 'چگونه می‌توان اسپانسر نمایشگاه شد؟', 'از طریق ثبت درخواست در وبسایت نمایشگاه و پس از بررسی و تایید شورای سیاست گذاری نمایشگاه.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('6VVPV48X', 'اطلاعات، غرفه‌داران', 'آیا اسپانسرشیپ نمایشگاه سطح های مختلفی دارد؟', 'خیر، اسپانسرشیپ نمایشگاه با شرایط واحد و مشخص برای تمامی حامیان نمایشگاه قابل اجرا است. برای اطلاع از خدمات تبلیغاتی و ساختن پکیج مد نظر خود با دبیرخانه تماس بگیرید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('VHJ6MR88', 'اطلاعات، غرفه‌داران', 'مزایا و خدمات قابل ارایه به اسپانسر نمایشگاه شامل چه مواردی می شوند؟', 'برای آگاهی از جزییات خدمات با دبیرخانه نمایشگاه تماس بگیرید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('1BQCOVGI', 'اطلاعات', 'چه گروه‌های کالایی در نمایشگاه حضور دارند؟', 'صنایع داروسازی، مواد اولیه دارویی (API)، بیوتکنولوژی، فناوری‌های آزمایشگاهی، بسته‌بندی، تجهیزات پزشکی، محصولات سلامت‌محور، آرایشی و بهداشتی و صنایع وابسته.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('RZ3QVXTI', 'اطلاعات', 'آیا شرکت‌های تولید دارو حضور دارند؟', 'بله، شرکت‌های تولیدکننده دارو در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('NBYLRR8G', 'اطلاعات', 'آیا شرکت‌های API حضور دارند؟', 'بله، شرکت‌های تولیدکننده مواد موثره دارویی API در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('6JNBWNR4', 'اطلاعات', 'آیا تولیدکنندگان مکمل حضور دارند؟', 'بله، شرکت‌های تولیدکننده مکمل در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('LP12VO4T', 'اطلاعات', 'آیا شرکت‌های تجهیزات دارویی حضور دارند؟', 'بله، شرکت‌های تولیدکننده تجهیزات دارویی در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('XVEQMFPA', 'اطلاعات', 'آیا شرکت‌های بسته‌بندی حضور دارند؟', 'بله، شرکت‌های بسته‌بندی در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('OR1QOJ1H', 'اطلاعات', 'آیا شرکت‌های بیوتکنولوژی حضور دارند؟', 'بله، شرکت‌های بیوتکنولوژی در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('FXDH2YU2', 'اطلاعات', 'آیا شرکت‌های صادراتی حضور دارند؟', 'بله، شرکت‌های دانش‌بنیان در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('J8DKKJRR', 'اطلاعات', 'آیا شرکت‌های توزیع دارو حضور دارند؟', 'بله، شرکت‌های توزیع دارو در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('05RZ01I9', 'اطلاعات', 'آیا شرکت‌های نرم‌افزاری دارویی حضور دارند؟', 'بله، شرکت‌های نرم‌افزاری دارویی در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('TYXAWUH7', 'اطلاعات', 'آیا شرکت‌های لجستیک حضور دارند؟', 'بله، شرکت‌های لجستیک در نمایشگاه ایران‌فارما حضور دارند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
