INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('NAES0CPL', 'اطلاعات، خدمات', 'آیا خدمات صادراتی ارائه می‌شود؟', 'بله، خدمات صادراتی از طریق شرکت‌های حاضر در نمایشگاه و دریافت مشاوره از سندیکا و سازمان‌های مرتبط وجود دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('F8TX91K9', 'اطلاعات، خدمات', 'آیا خدمات گمرکی معرفی می‌شود؟', 'بله، معرفی‌نامه گمرکی برای ترخیص بار شرکت‌های حاضر در نمایشگاه ارائه می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('IGQP0H0G', 'اطلاعات، خدمات', 'آیا خدمات بانکی معرفی می‌شود؟', 'بله، خدمات بانکی جهت تسهیل حضور و پرداخت به شرکت‌ها ارائه می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('XNTQ1FYL', 'اطلاعات، خدمات', 'آیا راهنمای بازار ایران وجود دارد؟', 'بله، راهنمای بازار ایران، علاوه بر انتشار گزارش‌های در اقلام چاپی، به صورت حضوری قابل ارائه است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('5BKP7Y44', 'اطلاعات', 'آیا کاتالوگ انگلیسی موجود است؟', 'بله، کاتالوگ انگلیسی موجود است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('K6ZOKR1S', 'اطلاعات، خدمات', 'آیا مرکز اطلاع‌رسانی بین‌الملل وجود دارد؟', 'بله، مرکز راهنمای بین‌الملل در ستون اطلاعات مستقر است و رادیوی نمایشگاه به صورت مستمر برنامه‌های مختلف را ارائه می‌کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('8X8WYPPL', 'اطلاعات، خدمات', 'رستوران کجاست؟', 'رستوران نمایشگاه در حیاط یاس، انتهای شبستان مستقر است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('3DCCHU8Z', 'اطلاعات، خدمات', 'کافی‌شاپ کجاست؟', 'کافه‌های نمایشگاه در حیاط یاس، انتهای شبستان مستقر است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('1HAA3C5O', 'اطلاعات، خدمات', 'نمازخانه کجاست؟', 'نمازخانه در نیم‌طبقه بالا، شبستان H واقع شده است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('7VYQBCRG', 'اطلاعات، خدمات', 'سرویس بهداشتی کجاست؟', 'سرویس بهداشتی، بیرون از شبستان اصلی، در مجاورت بال شمالی شبستان، و در حیاط یاس واقع شده است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('I9ENLYI6', 'اطلاعات، خدمات', 'اورژانس کجاست؟', 'اورژانس نمایشگاه در فضای باز بیرون از شبستان مستقر است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('U96HZI0L', 'اطلاعات، خدمات', 'دستگاه خودپرداز کجاست؟', 'نزدیک‌ترین دستگاه خودپرداز، خارج از فضای مصلا در خیابان شهید بهشتی است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('TKU2DJUN', 'اطلاعات، خدمات', 'اینترنت رایگان وجود دارد؟', 'خیر، دسترسی رایگان به اینترنت در نمایشگاه وجود ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('NFPM5M0L', 'اطلاعات، خدمات', 'وای‌فای چگونه دریافت می‌شود؟', 'امکان ارائه وای‌فای در نمایشگاه وجود ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ZXSDY7IJ', 'اطلاعات، خدمات', 'اشیای گمشده را کجا تحویل دهیم؟', 'لطفاً اشیای گمشده را به ستون اطلاعات، مستقر در وسط شبستان اصلی تحویل دهید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('QSYLJ6SY', 'اطلاعات، خدمات', 'مرکز اطلاعات کجاست؟', 'مرکز اطلاعات نمایشگاه در ستون اصلی، بین شبستان‌های E و D واقع شده است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('AVFYI0GK', 'اطلاعات، خدمات', 'آیا شارژر موبایل وجود دارد؟', 'بله، شارژر موبایل در سالن ورودی بازدیدکنندگان مستقر است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('003022D7', 'اطلاعات، خدمات', 'آیا خدمات چاپ وجود دارد؟', 'خیر، خدمات چاپ در نمایشگاه ارائه نمی‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('5NJB2L6I', 'اطلاعات، خدمات', 'آیا خدمات ترجمه وجود دارد؟', 'برای درخواست خدمات ترجمه می‌توانید با دبیرخانه تماس بگیرید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('1Q1QCUF3', 'اطلاعات، خدمات', 'آیا خدمات پستی وجود دارد؟', 'خیر، خدمات پستی در نمایشگاه وجود ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('6UJLGWGC', 'اطلاعات، خدمات', 'آیا خدمات تاکسی وجود دارد؟', 'خیر، خدمات تاکسی در نمایشگاه وجود ندارد. می‌توانید با استفاده از شاتل‌های نمایشگاه به صورت رایگان به ورودی‌های اصلی مصلا در خیابان شهید بهشتی و بزرگراه رسالت مراجعه کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('1U87IX4E', 'اطلاعات، خدمات', 'آیا امکان رزرو هتل وجود دارد؟', 'خیر، امکان رزرو هتل به صورت مستقیم از طریق دبیرخانه وجود ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('PEJG6AV5', 'اطلاعات، خدمات', 'آیا خدمات حمل بار وجود دارد؟', 'بله، خدمات حمل بار بیرون از شبستان مستقر هستند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('8XDR3DS1', 'اطلاعات، خدمات', 'آیا مرکز کسب‌وکار وجود دارد؟', 'بله، مرکز کسب و کار و جلسات ایران‌فارما لانژ در شبستان D مستقر است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('74956LA9', 'اطلاعات، خدمات', 'آیا فضای استراحت وجود دارد؟', 'فضای استراحت رایگان در حیات یاس (به جز زمان سرو ناهار) و فضای استراحت با تهیه کارت در فضای ایران‌فارما لانژ مستقر است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('MURZZ5QQ', 'اطلاعات، خدمات', 'آیا خدمات VIP وجود دارد؟', 'برای درخواست خدمات VIP می‌توانید با دبیرخانه تماس بگیرید، خدمات مختلفی برای این بخش در نظر گرفته شده است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('33YQVXD7', 'اطلاعات، خدمات', 'لیست شرکت‌کنندگان را از کجا دریافت کنم؟', 'امکان ارائه لیست شرکت‌کنندگان حقیقی وجود ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('WZD3G4PT', 'اطلاعات، خدمات', 'کاتالوگ نمایشگاه چگونه دریافت می‌شود؟', 'کاتالوگ نمایشگاه، علاوه بر مراکز توزیع، به صورت دیجیتال در وبسایت نمایشگاه بارگذاری می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('99EBDQTE', 'اطلاعات', 'اطلاعات تماس شرکت‌ها چگونه دریافت می‌شود؟', 'اطلاعات تماس شرکت‌ها در کتاب نمایشگاه منتشر می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('84YQXN09', 'اطلاعات', 'فیلم‌های نمایشگاه کجا منتشر می‌شود؟', 'فیلم‌های نمایشگاه در شبکه‌های نمایشگاه منتشر می‌شود. وبسایت کانال خبری این رویداد در تلگرام به ادرس T.ME/FDMAG مرجع اخبار رسمی این رویداد خواهد بود. علاوه بر آن ایران‌فارما در اینستاگرام، یوتیوب و .. صفحه دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('RVUW9BXW', 'اطلاعات', 'گزارش نمایشگاه منتشر می‌شود؟', 'گزارش نمایشگاه علاوه بر شبکه‌های اجتماعی در وبسایت نمایشگاه منتشر می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('TAYUEJG8', 'اطلاعات', 'آمار بازدیدکنندگان منتشر می‌شود؟', 'آمار بازدیدکنندگان نمایشگاه علاوه بر شبکه‌های اجتماعی در وبسایت نمایشگاه منتشر می‌شود، علاوه بر وبسایت کانال خبری این رویداد در تلگرام به ادرس T.ME/FDMAG مرجع اخبار رسمی این رویداد خواهد بود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('7W62429G', 'اطلاعات', 'تاریخ دوره بعدی نمایشگاه چیست؟', 'تاریخ دوره بعدی نمایشگاه به زودی از طریق شبکه‌های اجتماعی نمایشگاه اعلام می‌شود اما عمدتا این رویداد در ماه مهر (سپتامبر) برگزار می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('VLIE31GW', 'اطلاعات، ثبت‌نام', 'چگونه برای دوره بعد ثبت‌نام کنم؟', 'برای اطلاع از شیوه و زمان ثبت‌نام در دوره بعدی، شبکه‌های اجتماعی نمایشگاه را دنبال کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('TUIN7ZNG', 'اطلاعات، ثبت‌نام', 'آیا تخفیف ثبت‌نام زودهنگام وجود دارد؟', 'خیر، در حال حاضر برنامه‌ای برای تخفیف ثبت‌نام زودهنگام وجود ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('96S5F37Y', 'اطلاعات', 'چگونه بازخورد ثبت کنم؟', 'برای ثبت بازخورد و دسترسی به فرم نظرسنجی روی این لینک کلیک کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('LJC4TB6B', 'اطلاعات', 'آیا نظرسنجی برگزار می‌شود؟', 'برای ثبت بازخورد و دسترسی به فرم نظرسنجی روی این لینک کلیک کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('B2Y20RWX', 'اطلاعات', 'چگونه پیشنهاد همکاری ارسال کنم؟', 'می‌توانید با تماس با دبیرخانه، از طریق فرم ارتباط در وبسایت، و آدرس ایمیل نمایشگاه پیشنهاد همکاری ارسال کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('PH498XG5', 'غرفه‌داران', 'چگونه اسپانسر شویم؟', 'با ثبت‌نام در وبسایت نمایشگاه در مهلت اعلام شده، می‌توانید درخواست اسپانسرشیپ خود را ثبت کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('7WR30DWC', 'اطلاعات، ثبت‌نام', 'چگونه در کارگاه‌ها شرکت کنیم؟', 'بله، برای شرکت در کارگاه‌ها می‌توانید با مراجعه به وبسایت نمایشگاه در برنامه‌های مورد نظرتان ثبت‌نام کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('9EB3U3BC', 'اطلاعات', 'فایل ارائه سخنرانان منتشر می‌شود؟', 'فایل ارائه برخی از سخنرانی‌ها منتشر می‌شود.;کانال تلگرامی خبری نمایشگاه به نشانی T.ME/FDMAG نیز بعد از این رویداد فایل‌ها را منتشر خواهد کرد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('170IMSBO', 'اطلاعات', 'فیلم کارگاه‌ها در دسترس است؟', 'فیلم برخی از کارگاه‌ها پس از برگزاری در کانال یوتیوب نمایشگاه منتشر می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('QR4OG9AH', 'اطلاعات', 'آیا شبکه ارتباطی شرکت‌کنندگان حفظ می‌شود؟', 'شرکت‌کنندگان می‌توانند با رد و بدل کردن اطلاعات تماس خود، ارتباط خود را با یکدیگر حفظ کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('15TJ174P', 'اطلاعات', 'چگونه خبرنامه نمایشگاه را دریافت کنم؟', 'با ثبت‌نام در صفحه اصلی نمایشگاه می‌توانید خبرنامه نمایشگاه را دریافت کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('DNHMN7DY', 'اطلاعات', 'آیا عضویت سالانه وجود دارد؟', 'در حال حاضر امکان عضویت سالانه وجود ندارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('FM615AVS', 'اطلاعات، رویداد‌های جانبی', 'چگونه در رویدادهای جانبی شرکت کنم؟', 'برای شرکت در رویدادهای جانبی می‌توانید با مراجعه به  وب سایت نمایشگاه ایران‌فارما و پلتفرم نمایشگاه به نشانی IPHEXPO.COM در آن‌ها ثبت‌نام کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('TWI7EWSX', 'اطلاعات', 'چگونه در پنل‌های تخصصی سخنرانی کنم؟', 'برای سخنرانی در پنل‌های تخصصی با دبیرخانه تماس بگیرید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('D128UXQQ', 'اطلاعات', 'چگونه محصول جدید معرفی کنم؟', 'برای معرفی محصول جدید با دبیرخانه تماس بگیرید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('TINWGI81', 'اطلاعات', 'چگونه نمایندگی بگیرم؟', 'برای دریافت نمایندگی نمایشگاه در کشورهای دیگر با دبیرخانه تماس بگیرید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('NG1YFB9W', 'اطلاعات', 'چگونه تأمین‌کننده پیدا کنم؟', 'برای پیدا کردن تامین‌کننده مورد نظر می‌توانید به غرفه شرکت‌ها در نمایشگاه مراجعه کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('54PXQ6A3', 'اطلاعات', 'چگونه سرمایه‌گذار پیدا کنم؟', 'برای پیدا کردن تامین‌کننده مورد نظر می‌توانید به غرفه شرکت‌ها و فضاها و جلسات مرتبط در نمایشگاه مراجعه کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('AEXS9A3R', 'اطلاعات', 'چگونه صادرات را آغاز کنم؟', 'می‌توانید در کارگاه‌های صادرات نمایشگاه شرکت کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('FDB75UGI', 'اطلاعات', 'چگونه با برگزارکنندگان تماس بگیرم؟', 'برای تماس با برگزارکنندگان می‌توانید با شماره دبیرخانه تماس بگیرید یا به آدرس دبیرخانه info@iphexpo.com ایمیل ارسال کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('LQEIYXP8', 'اطلاعات', 'راه‌های ارتباط با پشتیبانی چیست؟', 'برای دریافت پشتیبانی می‌توانید با شماره دبیرخانه تماس بگیرید یا به آدرس دبیرخانه info@iphexpo.com ایمیل ارسال کنید.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('IRDDWMO6', 'اطلاعات', 'آیا آمار و گزارش نمایشگاه منتشر می‌شود؟', 'بله، گزارش نهایی و آمار مشارکت‌کنندگان پس از پایان نمایشگاه منتشر می‌شود که از طریق تب مستندات پلتفرم ایران فارما به نشانی IPHEXPO.COM  در دسترس است', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('J08K1B4Q', 'اطلاعات', 'چگونه از اخبار دوره‌های آینده مطلع شوم؟', 'با عضویت در خبرنامه و دنبال کردن کانال‌های رسمی نمایشگاه.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('C2MJ4RFD', 'اطلاعات، ثبت‌نام', 'آیا امکان پیش‌ثبت‌نام برای دوره بعدی وجود دارد؟', 'بله، پس از پایان هر دوره امکان پیش‌ثبت‌نام فراهم می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('NFOO9ZPX', 'اطلاعات', 'چگونه می‌توان به اطلاعات غرفه‌داران دسترسی داشت؟', 'از طریق تهیه دایرکتوری شرکت‌کنندگان و وب‌سایت نمایشگاه.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('M49P49SS', 'اطلاعات', 'چگونه می‌توان با تیم IPH Expo تماس گرفت؟', 'از طریق فرم تماس، ایمیل یا شماره‌های ارتباطی درج‌شده در وب‌سایت رسمی نمایشگاه به نشانی IPHEXPO.COM', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('P82T8PS6', 'خدمات', 'غرفه‌داران غرفه خام چه مسئولیتی دارند؟', 'باید شخصاً نسبت به ساخت و تجهیز غرفه اقدام کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('Y09CNVE8', 'خدمات', 'معرفی غرفه‌ساز تا چه تاریخی الزامی است؟', 'حداکثر تا ۲۱ شهریور.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('A6P5NFE5', 'اطلاعات', 'آیا امکان معرفی محصولات جدید در نمایشگاه بین‌المللی ایران فارما وجود دارد؟', 'بله. نمایشگاه بستری مناسب برای معرفی محصولات، فناوری‌ها، خدمات جدید و دستاوردهای نوآورانه شرکت‌ها به مدیران، متخصصان و فعالان صنعت داروسازی فراهم می‌کند', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('6MAYHHWW', 'اطلاعات', 'آیا برای شرکت‌کنندگان نمایشگاه بین‌المللی ایران فارما خدمات پذیرایی و ناهار در نظر گرفته می‌شود؟', 'بسته به نوع حضور و شرایط مشارکت، خدمات پذیرایی برای برخی از گروه‌ها و برنامه‌های نمایشگاه پیش‌بینی می‌شود. شرکت‌کنندگان می‌توانند برای اطلاع از جزئیات خدمات رفاهی و پذیرایی، شرایط پکیج حضور یا اطلاعات ارائه‌شده توسط دبیرخانه نمایشگاه را بررسی کنند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ZILC6LPQ', 'اطلاعات', 'آیا نمایشگاه بین‌المللی ایران فارما برای غرفه‌داران خدمات ناهار ارائه می‌دهد؟', 'خدمات رفاهی مانند پذیرایی و ناهار غرفه‌داران بر اساس سطح مشارکت و حمایت، متراژ نمایشگاهی و شرایط اعلام‌شده از سوی برگزارکننده ارائه می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('EQVRFUMF', 'اطلاعات', 'آیا برای مهمانان ویژه و هیئت‌های تجاری خدمات پذیرایی ویژه در نظر گرفته می‌شود؟', 'بله. برای مهمانان ویژه، هیئت‌های تجاری و برخی گروه‌های هدف، برنامه‌ها و خدمات متناسب با شرایط حضور آن‌ها می‌تواند در نظر گرفته شود تا تجربه حضور در نمایشگاه حرفه‌ای‌تر و هدفمندتر باشد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ISAU6L0C', 'اطلاعات', 'آیا نمایشگاه بین‌المللی ایران فارما خدمات اسکان برای شرکت‌کنندگان ارائه می‌دهد؟', 'خیر دبیرخانه برای شرکت‌کنندگان، غرفه‌داران و مهمانانی که از شهرها یا کشورهای دیگر حضور پیدا می‌کنند فضایی به عنوان اسکان در نظر نگرفته است. اما دانشجویان از طریق کمیته دانشجویی سندیکای صاحبان صنایع دارویی می‌توانند می‌توانند به صورت محدود از برخی فضاهای دانشجویی برای اسکان بهره‌مند شوند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('I7F8BPXC', 'اطلاعات', 'چرا نمایشگاه بین‌المللی ایران فارما یک فرصت استراتژیک برای فعالان صنعت دارو محسوب می‌شود؟', 'زیرا این رویداد تنها محل نمایش محصولات نیست؛ بلکه بستری برای ارتباط‌سازی، توسعه کسب‌وکار، شناخت بازار، انتقال دانش، معرفی نوآوری و ایجاد همکاری‌های بلندمدت در صنعت داروسازی است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('33P4MKSR', 'اطلاعات', 'آیا شرکت‌ها می‌توانند برند خود را در فضای نمایشگاه بیشتر در معرض دید قرار دهند؟', 'بله. علاوه بر غرفه، امکان استفاده از ظرفیت‌های تبلیغاتی، رسانه‌ای و فرصت‌های معرفی برند برای افزایش دیده‌شدن وجود دارد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('BJRO5SNQ', 'اطلاعات', 'آیا امکان دریافت مشاوره برای انتخاب نوع حضور در نمایشگاه وجود دارد؟', 'بله. تیم اجرایی نمایشگاه می‌تواند درباره نوع مشارکت، انتخاب فضای مناسب و خدمات مورد نیاز، راهنمایی‌های لازم را ارائه کند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('DODGH7TY', 'اطلاعات', 'آیا نمایشگاه بین‌المللی ایران فارما برنامه‌ای برای حمایت از نوآوری دارد؟', 'بله. بخش‌های فناورانه نمایشگاه با هدف معرفی ایده‌ها، فناوری‌های نوین و حمایت از ارتباط میان نوآوران و صنعت طراحی شده‌اند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('AOSTZXNX', 'خدمات', 'آیا دبیرخانه می‌تواند درخواست رزرو غرفه یا اسپانسری را رد کند؟', 'بله، دبیرخانه در پذیرش یا رد درخواست‌ها اختیار کامل دارد و درخواست شرکت‌هایی که با اهداف یا موضوع نمایشگاه مغایرت دارند رد خواهد شد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('7JN7TFX6', 'خدمات', 'در صورت تکمیل نکردن به‌موقع مراحل ثبت‌نام چه اتفاقی می‌افتد؟', 'رزرو غرفه لغو شده و وجوه پرداختی مسترد نخواهد شد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('8TV8TZKL', 'خدمات', 'هزینه مشارکت چه زمانی باید پرداخت شود؟', 'کل هزینه مشارکت باید هنگام ثبت‌نام و بر اساس فضای درخواستی پرداخت شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('N0WVHFWQ', 'خدمات', 'هزینه درج‌شده در فرم رزرو شامل چه خدماتی است؟', 'این مبلغ صرفاً بابت اجاره فضای نمایشگاهی است و هزینه پارتیشن‌بندی و ارائه خدمات مجزا خواهد بود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('MUQVRFFF', 'خدمات', 'آیا اطلاعات شرکت در کتاب نمایشگاه درج می‌شود؟', 'بله، پروفایل شرکت به‌صورت رایگان در کتاب رسمی نمایشگاه منتشر می‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('Y2X4ADBJ', 'خدمات', 'مسئولیت صحت اطلاعات درج‌شده در کتاب نمایشگاه بر عهده چه کسی است؟', 'مسئولیت آن بر عهده مشارکت‌کننده است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('ZAW6R6VV', 'خدمات', 'تا چه زمانی می‌توان درخواست تغییر نوع غرفه را ارائه کرد؟', 'تا پیش از ۲۱ شهریور ۱۴۰۵ به‌صورت مکتوب.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('N5PZG2W3', 'خدمات', 'چه کالاهایی مجاز به عرضه در نمایشگاه هستند؟', 'فقط کالاها و خدمات مرتبط با موضوع نمایشگاه یعنی دارو و صنایع وابسته', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('JNW98O0A', 'خدمات', 'محصولات عرضه‌شده باید چه ویژگی‌ای داشته باشند؟', 'باید از کیفیت مناسب برای ارائه در یک نمایشگاه بین‌المللی برخوردار باشند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('T19CP94J', 'خدمات', 'آیا برای درج بنر، نمایش پوستر و کاتالوگ نیاز به تأییدیه وجود دارد؟', 'بله، باید به تأیید دبیرخانه برسند.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('K27L8BS6', 'خدمات', 'آیا ارتفاع غرفه‌سازی محدودیت دارد؟', 'بله، باید به تأیید واحد خدمات نمایشگاهی دبیرخانه ایران فارما برسد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('VKH9ACE9', 'خدمات', 'در صورت مغایرت نقشه با ضوابط نمایشگاه چه می‌شود؟', 'اصلاحات لازم اعمال شده و رعایت آن برای مشارکت‌کننده الزامی است.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('SBYC9FWL', 'خدمات', 'مسئول خسارت‌های ناشی از عملکرد غرفه‌ساز چه کسی است؟', 'مشارکت‌کننده.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('273BTFJJ', 'خدمات', 'آیا نوشتن تبلیغات روی پشت سازه‌های مشرف به غرفه‌های مجاور مجاز است؟', 'خیر مجاز نیست', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('C6SNTT6Z', 'خدمات', 'انشعاب برق تا کجا تأمین می‌شود؟', 'تا نزدیک‌ترین پست برق سالن.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('K2J3V4TZ', 'خدمات', 'درخواست برق سه‌فاز چگونه انجام می‌شود؟', 'باید حداکثر تا ۱ شهریور به‌صورت کتبی اعلام شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('5F6WZKL6', 'خدمات', 'استفاده از پانل گچی و مصالح سنگین مجاز است؟', 'خیر مجاز نیست', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('OUP0PTNW', 'خدمات', 'آیا پس از تخصیص غرفه امکان انصراف وجود دارد؟', 'بله، اما وجه پرداختی مسترد نمی‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('IRUZUOU6', 'خدمات', 'آیا می‌توان متراژ رزرو شده را کاهش داد؟', 'خیر این امکان وجود ندارد', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('JA5EFSJV', 'خدمات', 'اگر غرفه تحویل گرفته شود اما مورد استفاده قرار نگیرد چه می‌شود؟', 'هیچ مبلغی بازگردانده نمی‌شود.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('B9AG9DJU', 'خدمات', 'آیا محل غرفه پس از اعلام ممکن است تغییر کند؟', 'بله، در شرایط خاص دبیرخانه می‌تواند محل غرفه را تغییر دهد.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
INSERT INTO public.faq (id, category, question, answer, created_at, updated_at) VALUES ('Q9MIS8XI', 'خدمات', 'غرفه‌سازی از چه تاریخی آغاز می‌شود؟', 'از ساعت ۸ صبح روز ۲۸ شهریور ۱۴۰۵.', '2026-08-08 16:49:32.716374', '2026-08-08 16:49:32.716374');
